mapper.select:
SELECT mst.*, mapp.tbl_seq, mapp.office_seq
FROM utb_cost_mst mst
INNER JOIN utb_cost_mapp mapp ON mst.mapping_cost_seq = mapp.mapping_cost_seq
WHERE mst.del_yn = 'N'
AND mapp.del_yn = 'N'

    AND mapp.tbl_seq = #{tblSeq}


    AND mapp.office_seq = #{officeSeq}


    AND mst.cost_category_code = #{costCategoryCode}

ORDER BY mst.create_at DESC

mapper.update:
UPDATE utb_cost_mst
SET del_yn = 'Y',
    update_at = CURRENT_TIMESTAMP
WHERE office_seq = #{officeSeq}
  AND mapping_cost_seq IN (
    SELECT mapping_cost_seq
    FROM utb_cost_mapp
    WHERE tbl_seq = #{tblSeq}
      AND office_seq = #{officeSeq}
      AND del_yn = 'N'
)

UPDATE utb_cost_mapp
SET del_yn = 'Y',
    update_at = CURRENT_TIMESTAMP
WHERE tbl_seq = #{tblSeq}
  AND office_seq = #{officeSeq}
  AND del_yn = 'N'

